CREATE OR REPLACE FUNCTION public.get_venue_active_count() RETURNS integer LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public, pg_temp AS $$ SELECT count(*)::integer FROM ( SELECT DISTINCT ON (player_id) player_id, event_type, created_at FROM public.venue_presence_events ORDER BY player_id, created_at DESC ) latest WHERE latest.event_type = 'enter' AND latest.created_at > now() - interval '3 hours'; $$;
